WITH unpacked AS (SELECT id, customer_id, created_at, coupon_codes, items, attributes, ship_to.zip AS ship_zip, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, attributes['device'] AS device, TRANSFORM(FILTER(items, item -> item.promo IS NOT NULL), item -> STRUCT(item.product_id AS pid, ROUND(item.price * 0.9, 2) AS discounted_price)) AS promo_lines FROM carts) SELECT customer_id, COUNT(DISTINCT id) AS distinct_ids, MIN(created_at) AS started_at, MAX(created_at) AS last_created_at, COUNT(DISTINCT device) AS distinct_devices, MAX(created_at) AS last_seen FROM unpacked GROUP BY 1 HAVING COUNT(DISTINCT device) < 1 ORDER BY distinct_devices DESC
